45	static int bm_eth_reset_phy(struct platform_device *pdev)
46	{
47		struct device_node *np = pdev->dev.of_node;
48		int phy_reset_gpio;
49		u32	ephy_base_addr = 0x0;
50		void __iomem *ephy_base_reg;
51		u32	ephy_top_addr = 0x0;
52		void __iomem *ephy_top_reg;
53	
54		if (!np)
55			return 0;
56	
57		of_property_read_u32(np, "ephy_base_reg", &ephy_base_addr);
58		of_property_read_u32(np, "ephy_top_reg", &ephy_top_addr);
59	
60		if (ephy_base_addr && ephy_top_addr) {
61			ephy_base_reg = ioremap(ephy_base_addr, 0x80);
62			ephy_top_reg = ioremap(ephy_top_addr, 0x10);
63	#ifdef CONFIG_PM_SLEEP
64	#if defined(CONFIG_ARCH_CV180X) || defined(CONFIG_ARCH_CV181X)
65			// set rg_ephy_apb_rw_sel 0x0804@[0]=1/APB by using APB interface
66			writel(0x0001, ephy_top_reg + 0x4);
67	
68			// Release 0x0800[0]=0/shutdown
69			writel(0x0900, ephy_top_reg);
70	
71			// Release 0x0800[2]=1/dig_rst_n, Let mii_reg can be accessabile
72			writel(0x0904, ephy_top_reg);
73			// ANA INIT (PD/EN), switch to MII-page5
74			writel(0x0500, ephy_base_reg + 0x7c);
75			// Release ANA_PD p5.0x10@[13:8] = 6'b001100
76			writel(0x0c00, ephy_base_reg + 0x40);
77			// Release ANA_EN p5.0x10@[7:0] = 8'b01111110
78			writel(0x0c7e, ephy_base_reg + 0x40);
79			// Wait PLL_Lock, Lock_Status p5.0x12@[15] = 1
80			//mdelay(1);
81	
82			// Release 0x0800[1] = 1/ana_rst_n
83			writel(0x0906, ephy_top_reg);
84	
85			// ANA INIT
86			// @Switch to MII-page5
87			writel(0x0500, ephy_base_reg + 0x7c);
88			// PHY_ID
89			writel(0x0043, ephy_base_reg + 0x8);
90			writel(0x5649, ephy_base_reg + 0xc);
91			// switch to MDIO control by ETH_MAC
92			writel(0x0, ephy_top_reg + 0x4);
93	#endif
94	#endif
95			iounmap(ephy_base_reg);
96			iounmap(ephy_top_reg);
97		}
98	
99		phy_reset_gpio = of_get_named_gpio(np, "phy-reset-gpios", 0);
100	
101		if (phy_reset_gpio < 0)
102			return 0;
103	
104		if (gpio_request(phy_reset_gpio, "eth-phy-reset"))
105			return 0;
106	
107		/* RESET_PU */
108		gpio_direction_output(phy_reset_gpio, 0);
109		mdelay(20);
110	
111		gpio_direction_output(phy_reset_gpio, 1);
112		/* RC charging time */
113		mdelay(60);
114	
115		return 0;
116	}
