118	void bm_dwmac_exit(struct platform_device *pdev, void *priv)
119	{
120		struct cvitek_mac *bsp_priv = priv;
121	
122		clk_disable_unprepare(bsp_priv->gate_clk_500m);
123		clk_disable_unprepare(bsp_priv->gate_clk_axi4);
