126	static int bm_dwmac_probe(struct platform_device *pdev)
127	{
128		struct plat_stmmacenet_data *plat_dat;
129		struct stmmac_resources stmmac_res;
130		struct cvitek_mac *bsp_priv = NULL;
131		int ret;
132	
133		pdev->dev.dma_mask = &bm_dma_mask;
134		pdev->dev.coherent_dma_mask = bm_dma_mask;
135	
136		bm_eth_reset_phy(pdev);
137	
138		ret = stmmac_get_platform_resources(pdev, &stmmac_res);
139		if (ret)
140			return ret;
141	
142		plat_dat = stmmac_probe_config_dt(pdev, &stmmac_res.mac);
143		if (IS_ERR(plat_dat))
144			return PTR_ERR(plat_dat);
145	
146		ret = stmmac_dvr_probe(&pdev->dev, plat_dat, &stmmac_res);
147		if (ret)
148			goto err_remove_config_dt;
149	
150		bsp_priv = devm_kzalloc(&pdev->dev, sizeof(*bsp_priv), GFP_KERNEL);
151		if (!bsp_priv)
152			return PTR_ERR(bsp_priv);
153	
154		bsp_priv->dev = &pdev->dev;
155	
156		/* clock setup */
157		bsp_priv->gate_clk_500m = devm_clk_get(&pdev->dev, "clk_500m_eth");
158	
159		if (IS_ERR(bsp_priv->gate_clk_500m))
160			dev_warn(&pdev->dev, "Cannot get clk_500m_eth!\n");
161		else
162			clk_prepare_enable(bsp_priv->gate_clk_500m);
163	
164		bsp_priv->gate_clk_axi4 = devm_clk_get(&pdev->dev, "clk_axi4_eth");
165	
166		if (IS_ERR(bsp_priv->gate_clk_axi4))
167			dev_warn(&pdev->dev, "Cannot get gate_clk_axi4!\n");
168		else
169			clk_prepare_enable(bsp_priv->gate_clk_axi4);
170	
171		plat_dat->bsp_priv = bsp_priv;
172		plat_dat->exit = bm_dwmac_exit;
173	
174		return 0;
175	
176	err_remove_config_dt:
177		stmmac_remove_config_dt(pdev, plat_dat);
178	
179		return ret;
180	}
