33	static int cv182xa_read_status(struct phy_device *phydev)
34	{
35		u32 lp_val, lp_val_cap, cap_val, cap_val_temp, i, ramdom_cap;
36		u32 get_random;
37		int err = genphy_read_status(phydev);
38		//pr_notice("link status=%x, retry_time=%x\n", phydev->link, retry_time);
39		if (retry_time > 0)
40			retry_time--;
41	
42		if (phydev->link == 0) {
43			if (retry_time == 0)
44				link_status = 0;
45	
46		} else if (phydev->speed == SPEED_100 && link_status == 0) {
47			link_status = 1;
48			lp_val = phy_read(phydev, 0x5);
49			pr_notice("lp1=%x\n", lp_val);
50			if (phydev->autoneg == AUTONEG_ENABLE && lp_val == 0x4d61) {
51				cap_val = phy_read(phydev, 0x4);
52				pr_notice("cap1=%x\n", cap_val);
53				get_random_bytes(&get_random, sizeof(int32_t));
54				//ramdom_cap = (get_random % 13) << 5;
55				//if(ramdom_cap == 0x160)
56				//{
57				//	ramdom_cap = 0x1e0;
58				//}
59				//cap_val_temp = cap_val & ~0x1e0 | ramdom_cap;
60				ramdom_cap =  get_random & 0xde0 | 0x20;
61				if (ramdom_cap == 0xd60) {
62					pr_notice("ramdom_cap=%x\n\n", ramdom_cap);
63					ramdom_cap = 0xde0;
64				}
65				cap_val_temp = cap_val & ~0xde0 | ramdom_cap;
66				phy_write(phydev, 0x4, cap_val_temp);
67				pr_notice("get_random=%x, ramdom_cap=%x, cap_val_temp=%x\n",
68					 get_random, ramdom_cap, cap_val_temp);
69				for (i = 0; i < 150; i++) {
70					if ((phy_read(phydev, 0x1) & 0x20) == 0)
71						break;
72	
73					mdelay(10);
74					}
75				pr_notice("i=%d\n", i);
76				phy_modify(phydev, MII_BMCR, BMCR_ISOLATE, BMCR_ANENABLE | BMCR_ANRESTART);
77				for (i = 0; i < 1000; i++) {
78					if (phy_read(phydev, 0x1) & 0x20)
79						break;
80					mdelay(10);
81				}
82				lp_val = phy_read(phydev, 0x5);
83				lp_val_cap = lp_val & 0xde0;
84				pr_notice(" %d, link status=%x, lp2=%x\n", i, phy_read(phydev, 0x1), lp_val);
85	
86				if (((phy_read(phydev, 0x1) & 0x4) != 0) && lp_val != 0 && lp_val_cap != ramdom_cap) {
87					retry_time = 10;
88					phy_write(phydev, 0x4, cap_val);
89					phy_modify(phydev, MII_BMCR, BMCR_ISOLATE, BMCR_ANENABLE | BMCR_ANRESTART);
90					for (i = 0; i < 1000; i++) {
91						if (phy_read(phydev, 0x1) & 0x20)
92							break;
93	
94						mdelay(10);
95					}
96					//mdelay(8000);
97					//lp_val = phy_read(phydev, 0x5);
98					pr_notice(" %d, true link status=%x, lp2=%x\n", i,
99						 phy_read(phydev, 0x1), phy_read(phydev, 0x5));
100				} else {
101					phydev->link = 0;
102					link_status = 0;
103					phy_write(phydev, 0x4, cap_val);
104					phy_modify(phydev, MII_BMCR, BMCR_ISOLATE, BMCR_ANENABLE | BMCR_ANRESTART);
105					//err = phy_start_aneg(phydev);
106					//lp_val = phy_read(phydev, 0x5);
107					//pr_notice("lp3=%x\n", lp_val);
108					pr_notice(" %d, false link status=%x, lp2=%x\n", i,
109						 phy_read(phydev, 0x1), phy_read(phydev, 0x5));
110				}
111	
112				//err = genphy_read_status(phydev);
113				//lp_val = phy_read(phydev, 0x5);
114				//pr_notice("lp3=%x\n", lp_val);
115			}
116		}
117		pr_debug("%s, speed=%d, duplex=%d, ", __func__, phydev->speed, phydev->duplex);
118		pr_debug("pasue=%d, asym_pause=%d, autoneg=%d ", phydev->pause, phydev->asym_pause, phydev->autoneg);
119	
120		return err;
121	}
